const state = $getWorkflowStaticData('global');
// 上线时固定起点，不补发启用前的历史版本；这个时间随成功执行持久化。
state.enabledAt ??= new Date().toISOString();
return ['metasequoiaime/msime', 'metasequoiaime/msime-windows'].map(repository => ({json: {repository}}));

const crypto = require('crypto');
const platformFor = (repository, tag) => {
  if (repository === 'metasequoiaime/msime-windows' && /^v\d+\.\d+\.\d+$/.test(tag)) return 'Windows';
  if (repository !== 'metasequoiaime/msime') return null;
  const match = /^(windows7|windows|macos|linux|android|ios|harmony)-v\d+\.\d+\.\d+$/.exec(tag);
  return match ? {windows7: 'Windows 7', windows: 'Windows', macos: 'macOS', linux: 'Linux', android: 'Android', ios: 'iOS', harmony: 'HarmonyOS'}[match[1]] : null;
};
const repositories = $('准备发布仓库').all();
const state = $getWorkflowStaticData('global');
const cutoff = Date.parse(state.enabledAt);
if (!Number.isFinite(cutoff)) throw new Error('客户端分发启用时间无效');
const now = Date.now();
const candidates = new Map();
state.sourceErrors ??= {};
for (const [index, item] of $input.all().entries()) {
  const repository = repositories[index]?.json.repository;
  if (!repository) throw new Error('客户端仓库关联缺失');
  const response = item.json;
  const releases = response.body ?? response;
  if (response.error || Number(response.statusCode ?? 200) >= 400 || !Array.isArray(releases)) {
    state.sourceErrors[repository] = {checked_at: new Date().toISOString(), status: Number(response.statusCode ?? 0)};
    continue;
  }
  delete state.sourceErrors[repository];
  for (const release of releases) {
    const tag = String(release.tag_name ?? '');
    const published = Date.parse(release.published_at);
    const platform = platformFor(repository, tag);
    if (!platform || release.draft || release.prerelease || !Number.isFinite(published) ||
        published < cutoff || published < now - 86400000 || published > now) continue;
    // 等附件上传完成后再发公告，空发行页留到下一轮检查。
    if (!Array.isArray(release.assets) || !release.assets.length ||
        release.assets.some(asset => asset.state !== 'uploaded' || !(asset.size > 0))) continue;
    const payload = {
      schema_version: 1, event: 'release.published', idempotency_key: `${repository}:${tag}`, repository,
      release: {tag, name: release.name || tag, body: release.body || '', url: release.html_url,
        published_at: release.published_at, target_commitish: release.target_commitish || ''},
    };
    if ($env.MSIME_RELEASE_WATCH_DRY_RUN === '1') payload.dry_run = true;
    candidates.set(payload.idempotency_key, {payload, published});
  }
}
state.lastCheckAt = new Date().toISOString();
state.lastCandidateCount = candidates.size;
const secret = $env.MSIME_SOCIAL_WEBHOOK_SECRET;
if (!secret) throw new Error('缺少社交 webhook 签名密钥');
return [...candidates.values()].sort((a, b) => a.published - b.published).map(({payload}) => {
  const body = JSON.stringify(payload);
  return {json: {body, signature: 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex')}};
});

const rows = $input.all();
const failures = rows.filter(item => item.json.error || Number(item.json.statusCode ?? 200) >= 400).length;
const state = $getWorkflowStaticData('global');
state.lastDispatch = {checked_at: new Date().toISOString(), requests: rows.length, failures};
return [{json: state.lastDispatch}];
